To create a program that reads a file system of a hard drive, you would need to use a programming language that has access to the file system APIs. Here's a basic example in Python using the built-in `os` and `pathlib` modules:

```python
import os
import pathlib

def read_file_system(path):
    try:
        for root, dirs, files in os.walk(path):
            print(f"Directory: {root}")
            for file in files:
                print(f"File: {file}")
    except FileNotFoundError:
        print(f"Error: The path '{path}' does not exist.")

def read_file_system_with_pathlib(path):
    try:
        path_obj = pathlib.Path(path)
        for entry in path_obj.iterdir():
            if entry.is_dir():
                print(f"Directory: {entry}")
            elif entry.is_file():
                print(f"File: {entry}")
    except FileNotFoundError:
        print(f"Error: The path '{path}' does not exist.")

# Example usage
read_file_system('/path/to/directory')
read_file_system_with_pathlib('/path/to/directory')
```

